    # 跨重启保留；复查到期不消费、不记审计。
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = (
            bucket["proofs"].get(proof_id)
            if bucket is not None else None
        )
        if row is None:
            return False, f"证明不存在: {proof_id}"
