def verify_proof(
    self,
    tenant_id: str,
    proof_id: str,
    proof: Any,
    challenge: Any = CHALLENGE_UNSET,
) -> Tuple[bool, str]:
    """以存储记录为锚校验谓词证明，返回 (是否有效, 失败原因)。

    校验顺序：请求 -> 资源 ID -> 绑定（字段集合与各锚定字段、
    请求 challenge、证明 challenge 与 proof 覆盖的存储 challenge
    三者一致）-> 已消费（优先于过期）-> 过期（当前时间 >=
    expires_at）-> 按存储凭证 claims 与存储 predicates 重算
    results 并核对 -> proof 格式与签名。验签成功后在消费锁内
    复查已消费/到期：复查到期即返回“证明已过期”，不消费、不记
    审计；签发密钥吊销、签发 DID 停用、凭证过期/暂停/已吊销均在
    验签与锚定成功后按序拒绝（证明自身过期优先于暂停与吊销），
    已吊销返回“凭证已吊销：<首次原因>”，同样不消费、不记审计；
    未到期并发验证仅一次成功，成功时原子标记已消费并记一次
    proof.consumed（同一次原子写，失败回滚），跨重启保留。

    可选持有者绑定按存储记录是否含 holder_did 判定：绑定证明必须
    恰含十二个字段（删持有者字段按未绑定通过、未绑定记录附加绑定
    字段均拒绝）。持有者字段缺失、类型错误、与存储记录或凭证
    subject_did 不符、持有者未知/已停用、所用历史版本公钥不可用或
    已吊销、holder_proof 签名失败，一律返回
    “持有者绑定校验失败”，不消费、不记审计。持有者签名与状态检查
    位于签发者校验之后、凭证有效期及状态判定之前，较早的既有失败
    优先；消费提交时持有者已停用或所用版本已吊销按同一原因拒绝。
    任何失败均返回非空中文原因，绝不抛异常、不泄露私钥。
    """
    if not isinstance(proof, dict):
        return False, "请求不合法: 字段 proof 必须为 JSON 对象"

    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = (
            bucket["proofs"].get(proof_id)
            if bucket is not None else None
        )
        if row is None:
            return False, f"证明不存在: {proof_id}"

        if challenge is CHALLENGE_UNSET:
            return False, "请求缺少字段: challenge"

        # 持有者绑定证明按存储记录是否含 holder_did 判定。
        is_holder_bound = "holder_did" in row
        holder_fields = {
            "holder_did",
            "holder_key_version",
            "holder_proof",
        }
        expected_keys = {
            "proof_id",
            "credential_id",
            "issuer_did",
            "issuer_key_version",
            "predicates",
            "results",
            "challenge",
            "expires_at",
            "proof",
        }
        if is_holder_bound:
            expected_keys |= holder_fields
        if set(proof) != expected_keys:
            # 差异仅涉及持有者字段时（绑定证明删字段或未绑定记录附加
            # 绑定字段）归为持有者绑定校验失败；其余结构差异沿用既有
            # 锚定原因。
            submitted = set(proof)
            diff_holder_only = (
                submitted - holder_fields ==
                expected_keys - holder_fields
            )
            if diff_holder_only:
                return False, "持有者绑定校验失败"
            return False, (
                "锚定校验失败: proof 字段集合与存储记录不一致"
            )
